\label{thm-IRB}
For nearest-neighbor lattice trees and lattice animals in dimensions $d\geq 16$ and $d\geq 17$, respectively, there exist constants $\bar{A}_1(d)$ and $\bar{A}_2(d)$ such that
    	\begin{equation} 
    	\label{e:IRB}
    	|\hat{\bar{G}}_z(k)|\leq \frac{\bar{A}_1(d)}{\chi(z)^{-1}+z[1-\hat{D}(k)]}
	\quad\qquad
	\text{and}
	\quad\qquad
	|\hat{\bar{G}}_z(k)|\leq \frac{\bar{A}_2(d)}{1-\hat{D}(k)},
    	 \end{equation}
uniformly for $z\leq z_c(d)$.

\label{thm-bds-crit}
For nearest-neighbor lattice trees the following upper bounds hold:
{\rm \begin{center}
\begin{tabular}{|r||  c|c | c|c |c|c|}
  \hline
  $d$             & 16& 17   & 18 & 19  & 20  & 30 \\
  \hline
    $\max\{\bar{A}_1(d),\bar{A}_2(d)\}\leq$      &3.872 &3.501 & 3.37    &3.284 & 3.222 & 2.973 \\
    $\frac 1 {g_{z_c}} \max\{\bar{A}_1(d),\bar{A}_2(d)\}\leq$      &1.293&1.182 & 1.147   & 1.125& 1.11& 1.052  \\
    $g_{z_c}\leq$      &2.9963 & 2.9619 & 2.9383 & 2.9196 &  2.9043 & 2.8268  \\
  $(2d-1)g_{z_c} z_c(d)\leq$       &1.1023& 1.0897 &1.081 & 1.0741&  1.0685  & 1.04  \\
 \hline
\end{tabular}
\end{center}
}
\noindent
For nearest-neighbor lattice animals the following upper bounds hold:
{\rm \begin{center}
\begin{tabular}{|r|| c|  c|c |c|c|}
  \hline
  $d$              & 17 & 18 & 19  & 20  & 30 \\
  \hline
    $\max\{\bar{A}_1(d),\bar{A}_2(d)\}\leq$       &3.587& 3.41  &3.309 & 3.24 &  2.975\\
    $\frac 1 {g_{z_c}} \max\{\bar{A}_1(d),\bar{A}_2(d)\}\leq$      & 1.21&  1.158   &1.132 &1.114 &1.053  \\
    $g_{z_c}\leq$       & 2.9721&2.9454  &2.925 &  2.9086& 2.8277   \\
  $(2d-1)g_{z_c} z_c(d)\leq$      & 1.0934&1.0836 &1.0761& 1.07 & 1.0403  \\
 \hline
\end{tabular}
\end{center}
}

\label{thm-k-space}
For nearest-neighbor LTs and LAs in dimensions $d\geq 16$ and $d\geq 17$, respectively, there exists a constant $\bar{A}(d)$ such that, as $|k|\rightarrow 0$,
    	\begin{equation} 
    	\label{e:k-space}
    	\hat{\bar{G}}_{z_c}(k)=\frac{\bar{A}(d)}{|k|^2}(1+o(1)).
    	 \end{equation}

\label{thm-x-space}
For nearest-neighbor LTs and LAs in dimensions  $d\geq 27$,                                                          
and with the constant $\bar{A}(d)$ as in Theorem \ref{thm-k-space}, as $|x|\rightarrow \infty$,
    	\begin{equation} 
    	\label{e:x-space}
    	\bar{G}_{z_c}(x)=\frac{a_d\bar{A}(d)}{|x|^{d-2}}(1+O(|x|^{-2/d})),
	\qquad
	\text{with}
	\qquad
	a_d=\frac{d\Gamma(d/2-1)}{2\pi^{d/2}}.
    	 \end{equation}

Before introducing non-backtracking random walk, we introduce some notation that will be used throughout this document. We exclusively use the Greek letters $\iota$ and $\kappa$ for values in $\{-d,-d+1,\dots,-1,1,2,\dots,d\}$ and denote the unit vector in direction $\iota$ by $\ve[\iota]\in\mathbb{Z}^d$, e.g. $(\ve[\iota])_i=\text{sign}(\iota) \delta_{|\iota|,i}$. We use ${\mathbb C}^{2d}$-valued and ${\mathbb C}^{2d}\times{\mathbb C}^{2d}$-valued quantities. For a clear distinction between scalar-, vector- and matrix-valued quantities, we always write ${\mathbb C}^{2d}$-valued functions with a vector arrow (e.g.\ $\vec v$) and matrix-valued functions with bold capital letters (e.g.\ ${\bf M}$). We do not use $\{1,2,\dots,2d\}$ as the index set for the elements of a vector or a matrix, but use $\{-d,-d+1,\dots,-1,1,2,\dots,d\}$ instead. We denote the identity matrix by ${\bf I}\in{\mathbb C}^{2d\times 2d}$ and the all-one vector by $ \v1 =(1,1,\dots,1)^T\in{\mathbb C}^{2d}$. Moreover, we define the matrices ${\bf J},\mD[k]\in{\mathbb C}^{2d\times 2d}$ by
	\begin{eqnarray}
  	\label{e:J-D-matrix-def}
	({\bf J})_{\iota,\kappa}=\delta_{\iota,-\kappa}\qquad\text{ and }\qquad
	(\mD[k])_{\iota,\kappa}=\delta_{\iota,\kappa} {\mathrm e}^{{\mathrm i} k_\iota},
	\end{eqnarray}
where $k\in[-\pi,\pi]^d$ and for negative index $\iota\in\{-d,-d+1,\dots,-1\}$, we write $k_\iota=-k_{|\iota|}$. Now we can introduce non-backtracking random walk and its Green's function.

\label{prop-LE}
For every $x\in \Zbold^d$, $\iota,\kappa\in \{\pm1,\pm2, \dots, \pm d\}$, the following recursion relations hold:
    \begin{align} 
    G_z(x)&=\delta_{0,x}+\mu_z\sum_{y\in\mathbb{Z}^d, \kappa\in\{\pm 1,\dots,\pm d\}} (\delta_{0,y}+\Psi_{z}^\kappa(y))G^{\kappa}(x-y+\ve[\kappa])+\Xi_{z}(x),
    \label{e:Gx-in-ex-1}\\
    G_z(x)&=G^\iota_z(x)+\mu_z G^{-\iota}_z( x-\ve[\iota])
        +\sum_{y\in\mathbb{Z}^d, \kappa\in\{\pm 1,\dots,\pm d\}} \Pi_{z}^{\iota,\kappa}(y) G_z^{\kappa}(x-y+\ve[\kappa])+\Xi_{z}^{\iota}(x),
    \label{e:Gx-in-ex-2}
     \end{align}
where
    \begin{align} 
    \label{e:PhiPsialt}
    \Pi_{z}^{\iota,\kappa}(x) &= \sum_{N=0}^{\infty} (-1)^N    \Pi^{\ssc[N],\iota,\kappa}(x),
    \qquad
    \Xi_{z}(x)= \sum_{N=0}^{\infty} (-1)^N \Xi^{\ssc[N]}_z(x),\\
   \label{e:PhiPsialt-2}
    \Psi_{z}^\kappa(x)&=\sum_{N=0}^{\infty} (-1)^N \Psi^{\ssc[N],\kappa}_z(y),
    \qquad
    \Xi_{z}^\iota(x)=\sum_{N=0}^{\infty} (-1)^N \Xi^{\ssc[N],\iota}(x),\\
    \mu_z &=  zg^\iota_z,\qquad\qquad\qquad\qquad\qquad \bar {\mu}_z =  zg_z.
   \label{e:Definition-aaz}
     \end{align}
Explicit formulas for the above lace-expansion coefficients are given in Section \ref{sec-defineCoeff}.

\label{prop-bds-LEC}
For each $N\geq 0$, the NoBLE coefficients
$ \Pi^{\ssc[N],\iota,\kappa}(y),$ $\Xi^{\ssc[N]}(x),$ $\Psi^{\ssc[N],\kappa}(y)$ and $\Xi^{\ssc[N],\iota}(x)$  can be bounded by a finite combination of sums and products of simple diagrams.

\label{defLTFirstPointIntersect}
For a sausage-walk $\omega$, a lace $L=\{s_1t_1,s_2t_2,$ $\dots,$ $s_Mt_M\}$ and $i\leq M$, we define $W_i(\omega)$  to be the set of vertices $w$ that are contained in both $A^\omega_{s_i}$ and $A^\omega_{t_i}$, such that $b^{A^\omega_{s_i}}(\overline{b}^\omega_{s_i},w)$ and $A^\omega_{t_i}(\overline{b}^\omega_{t_i},w)$ only intersect at $w$. If $W_i(\omega)$ is non-empty, then we define $w_i(\omega)$ to be the smallest in the set $W_i(\omega)$.
We call $w_i(\omega)$ the \emph{first intersection point} of $A^\omega_{s_i}$ and $A^\omega_{t_i}$.

\label{defSkeletonLA}
Let $x_0=0\in\mathbb{Z}^d$ and $n\in\{1,2,3,4\}$. For each $i\in\{1,\dots,n\}$, let $x_i\in\mathbb{Z}^d, l_i\in\Nbold$, the index $j_i\in\{l_i,\underline l_i\}$, $s_i\in\{+,-\}$, and let $\omega^i$ be a sausage-walk from $x_{i-1}$ to $x_i$. We define $S^{s_1,\dots,s_n}_{j_1,\dots,j_n}(\omega^1,\dots,\omega^n)$ to be the indicator that the following holds:
\begin{enumerate}[(1)]
\item There exists a sequence of paths $(p^i)_{i=1}^n$ such that $p^i$ is a path from $x_{i-1}$ to $x_i$ and $p^i$ uses only edges in $\omega^i$, each path $p^i$ describes a self-avoiding walk and all paths are pairwise bond-disjoint;
\item For each $i\in\{1,\dots,n\}$, we can choose $p^i$ in item (1) such that, $|p^i|\geq l_i$ when $j_i=l_i$, while $|p^i|=l_i$ when $j_i=\underline l_i$;
\item For each $i\in\{1,\dots,n\}$, the sausages of the walk $(A^{\omega^i}_j)_{j=0,\dots,|\omega^i|}$ do not intersect, so that $\omega^i$ describes a LA.
\item For each $i\in\{1,\dots,n\}$,
if $s_i=+$ then $A^{\omega^i}_{0}=\varnothing$, while $A^{\omega^i}_{|\omega^i|}=\varnothing$ when $s_i=-$.
\end{enumerate}

\label{def-repulsive-diamgrams}
For $i=1,2,3,4$ let $x_i\in \mathbb{Z}^d,\ l_i\in\Nbold,\ j_i\in\{l_i,\underline l_i\}$ and $x_0=0$. We define
	\begin{align}
	\mathscr{B}_{j_1,j_2}&(x_1,x_2)
 	\label{e:defLTBubble}
	=\max_{s_1,s_2\in\{+,-\}}\sum_{\omega^1\in\mathcal{W}(x_0,x_1)} \sum_{\omega^2\in\mathcal{W}(x_1,x_2)}
	\left(\prod_{i=1}^2 z^{|\omega^i|} Z[0,|\omega^i|]\right) S^{s_1,s_2}_{j_1,j_2}(\omega^1,\omega^2),\\
	\mathscr{T}_{j_1,j_2,j_3}&(x_1,x_2,x_3)\nonumber\\
	=&\max_{s_1,s_2,s_3\in\{+,-\}}

	\sum_{\footnotesize\begin{array}{c}
        \omega^1\in\mathcal{W}(x_0,x_1)\\
        \omega^2\in\mathcal{W}(x_1,x_2)\\
        \omega^3\in\mathcal{W}(x_2,x_3)
      	\end{array}}
	\left(\prod_{i=1}^3 z^{|\omega^i|} Z[0,|\omega^i|]\right) S^{s_1,s_2,s_3}_{j_1,j_2,j_3}(\omega^1,\omega^2,\omega^3),
 	\label{e:defLTTriangle} \\
	\mathscr{S}_{j_1,j_2,j_3,j_4}&(x_1,x_2,x_3,x_4)\nonumber\\
	=&\max_{s_1,s_2,s_3,s_4\in\{+,-\}}\sum_{\omega^1\in\mathcal{W}(x_0,x_1)}\sum_{\omega^2\in\mathcal{W}(x_1,x_2)}\sum_{\omega^3\in\mathcal{W}(x_2,x_3)}\sum_{\omega^4\in\mathcal{W}(x_3,x_4)}\nonumber\\
	&\qquad\qquad\qquad\qquad\times\left(\prod_{i=1}^4 z^{|\omega^i|} Z[0,|\omega^i|]\right) S^{s_1,s_2,s_3,s_4}_{j_1,j_2,j_3,j_4}(\omega^1,\omega^2,\omega^3,\omega^4).
	 \label{e:defLTSquare}
	\end{align}
Further, for $i\in\{1,\dots,n\}$ and $x\in\mathbb{Z}^d$, we define
	\begin{align}
	 \label{e:defLTDouble}
    	\mathscr{D}_i(x)=\sum_{A\colon 0,x\in A} \1_{\{0 \stackrel{A}{\Longleftrightarrow}  x\}}\1_{\{d_A(0,x)\geq i\}}z^{|A|}.
	\end{align}

\label{BoundNZero-Xi}
Let $0\leq z<z_c$. Then,
	\begin{align}
	\label{e:Bound-Xi0}
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[0]}_z(x)&\leq \frac {\1^{a} } {g_z} \sum_x\mathscr{D}_{1}(x),\qquad\quad
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[0]}_{{ \scriptscriptstyle  R},z}(x) \leq \frac {\1^{a}} {g_z} \mathscr{D}_{2}(x),\\
	\label{e:Bound-Psi0RemII}
	\sum_{x\in\mathbb{Z}^d} \Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, II},z}(x)&\leq \frac {2d-2}{2d} \frac {\1^{a}} {g^\iota_z} \mathscr{D}_{2}(x,0),
	\end{align}
and
	\begin{align}
	\label{e:Bound-Xi0W}
	\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[0]}_z(x)&\leq \frac {\1^{a}} {2}
	\sum_x|x|^2  G_z(x) 2dz (D \star \tilde G_z)(x),\\
	\label{e:Bound-Xi0RemW}
	\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[0]}_{{ \scriptscriptstyle  R},z}(x)&\leq \frac {\1^{a}} {2}
	\sum_x|x|^2  G_z(x) (2dz)^2g_z (D^{\star 2} \star \tilde G_z)(x),\\
	\label{e:Bound-Psi0RemIIW}
	\sum_{x\in\mathbb{Z}^d} |x|^2 \Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, II},z}(x)&\leq \frac {2d-2}{2d} \frac {\1^{a}} {2}
	\sum_x|x|^2  G_z(x)  (2dz)^2g_z (D^{\star 2} \star \tilde G_z)(x).
	\end{align}
Further,
	\begin{align}
	\label{e:Bound-Psi0RemI}
	\sum_{x\in\mathbb{Z}^d} \Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, I},z}(x)\leq& \frac {\1^{a}} {g_z^\iota}\big(
	(2d-1) \mathscr{B}_{\underline 1,3}(\ve[1],0)+\frac {2d-2}{2d} \sum_x\mathscr{B}_{2,2}(x,0)\big),\\


	\label{e:Bound-Psi0RemIW}
	\sum_{x\in\mathbb{Z}^d} |x-\ve[\kappa]|^2 \Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, I},z}(x)\leq &
	4d\1^{a} \mathscr{B}_{\underline 1,3}(\ve[1],0)\\
	&+ \frac {\1^{a}} {2}\sum_x (1+|x|^2)(2dz)^2g_z (D^{\star 2} \star \tilde G_z)(x) G_z(x).\nonumber
	\end{align}

\label{BoundNZero-XiIota}
Let $0\leq z< z_c$. Then,
	\begin{align}
	\label{e:Bound-XiIota0}
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[0],\iota}_z(x)\leq& G_z(\ve[\iota]) +\alpha_{1,0},\\
	\label{e:Bound-XiIota0Wa}
	\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[0],\iota}_z(x)\leq&\beta_{0},\\
	\label{e:Bound-XiIota0Wb}
	\sum_{x\in\mathbb{Z}^d}|x-\ve[\iota]|^2\Xi^{\ssc[0],\iota}_z(x)\leq& G_z(\ve[\iota]) +\gamma_1.
	\end{align}
The remainder terms of the split are bounded in a similar way as
	\begin{align}
	\label{e:Bound-XiIota0RemI}
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, I},z}(x)\leq& \alpha_{1,2},\qquad \qquad
	\sum_{x\in\mathbb{Z}^d}|x-\ve[\iota]|^2\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, I},z}(x)\leq \gamma_2,\\
	\label{e:Bound-XiIota0RemII}
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, II},z}(x)\leq& \alpha_{2,1},\qquad\qquad
	\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, II},z}(x)\leq\beta_{1}.
	\end{align}
The explicit terms of the splits are bounded by
	\begin{align}
	\label{e:Bound-XiIotaAlphaI}
	\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[\iota])\leq &\frac {\1^{a}}{g_z}\mathscr{D}_{1}(\ve[\iota]),\quad\qquad\qquad

	\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  II},z}(0)\leq G_z(\ve[\iota]),\\
    	\label{e:Bound-XiIotaAlphaIWa}
	\sum_\kappa \Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[\kappa]+\ve[\iota])\leq&
    	G_z(\ve[\iota])+ \frac {\1^{a}}{g_z}\sum_{\kappa\colon \kappa\neq -\iota}\mathscr{T}_{1,\underline 1,2}(\ve[\iota],\ve[\kappa]+\ve[\iota],0)
    	+\frac {zg_z^\iota}{g_z}\1^{a}\sum_{\kappa\colon \kappa\neq -\iota}\mathscr{B}_{2,2}(\ve[\iota]+\ve[\kappa],0),\\
    	\label{e:Bound-XiIotaAlphaIIWb}
    	\sum_\kappa \Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  II},z}(\ve[\kappa])\leq&
   	\frac {\1^{a}}{g_z}\mathscr{D}_{1}(\ve[\iota])+\frac {\1^{a} z g_z^\iota}{g_z}\sum_{\kappa\colon \kappa\neq -\iota}\sup_{x\neq 0}\tilde G_{1,z}(x)\sum_{u}\mathscr{B}_{1,1}(u,\ve[\kappa]),\\
   	&+ \1^{a}\sum_{\kappa\colon \kappa\neq -\iota} \Big(\frac{1}{g_z}\mathscr{T}_{1,2,\underline 1} (\ve[\iota],\ve[\kappa],0)
    	+ \1^{a}  z G_{3,z}(\ve[\kappa])\big(\tilde G_{1,z}(\ve[\iota])+\tilde G_{2,z}(\ve[\kappa]-\ve[\iota])\big)\Big).\nonumber
	\end{align}



We bound the terms in the split of $\Pi^{\ssc[0],\iota,\kappa}_z$ as
	\begin{align}
	\label{e:Bound-Pi0AlphaI}
	\sum_{\kappa}\Pi^{\ssc[0],\iota,\kappa}_{\alpha,z}(\ve[\iota])\leq&  \1^{a}(2d-1)z\mathscr{D}_{1}(\ve[\iota]),\\
	\label{e:Bound-Pi0RemI}
	\sum_{x\in\mathbb{Z}^d}\sum_{\iota}\Pi^{\ssc[0],\iota,\kappa}_{{ \scriptscriptstyle  R},z}(x)\leq& (2d-1)zg_z G_z(\ve[\iota]) +zg_z\alpha_{1,1},\\
	\label{e:Bound-Pi0RemIW}
	\sum_{x,\iota,\kappa}|x-\ve[\iota]|^2\Pi^{\ssc[0],\iota,\kappa}_{{ \scriptscriptstyle  R},z}(x+\ve[\kappa])\leq&
	2(2d)^2zg_z G_z(\ve[\iota]) +(2d)^2zg_z\gamma_1+4d(d+1)zg_z\alpha_{1,1}.
	\end{align}

\label{LemmaBoundXiLTOne}
Let $0\leq z< z_c$. Then,
	\begin{align}
	\label{e:Bound-Xi1}
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[1]}_z(x)&\leq \frac {g_z^\iota}{g_z} (\vec P)_0,\\
	\label{e:Bound-Xi1Rem}
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[1]}_{{ \scriptscriptstyle  R},z}(x) &\leq \frac {g_z^\iota}{g_z}\Big( (\vec P)_0
	- \sum_{x\in\mathbb{Z}^d} A^{0,0}(0,0,x,x)+2\mathscr{B}_{2,2}(x,0)+\sum_w \mathscr{T}_{2,1,1}(x,w,0)
	 \Big),\\
	\label{e:Bound-Psi1RemI}
	\sum_{x\in\mathbb{Z}^d} \Psi^{\ssc[1],\kappa}_{{ \scriptscriptstyle  R, I},z}(x)&\leq
	\frac {g_z^\iota}{g_z} \Big( (\vec P)_0 - \sum_{x\in\mathbb{Z}^d} A^{0,0}(0,0,x,x)+2\1_{\{\ve[\kappa]\neq x\}}\mathscr{B}_{\underline 1,3}(x,0)\Big)\\
	&+\frac {g_z^\iota}{g_z} \sum_{x\in\mathbb{Z}^d} \Big(2\mathscr{B}_{2,2}(x,0)+\sum_w \mathscr{T}_{1,1,1}(x,w,0)\Big),\nonumber\\
	\label{e:Bound-Psi1RemII}
	\sum_{x\in\mathbb{Z}^d} \Psi^{\ssc[1],\kappa}_{{ \scriptscriptstyle  R, II},z}(x)&\leq \frac {g_z^\iota}{g_z} \Big( (\vec P)_0
	- \sum_{x\in\mathbb{Z}^d} A^{0,0}(0,0,x,x)+2\mathscr{B}_{2,2}(x,0)+\sum_w \mathscr{T}_{2,1,1}(x,w,0)
	 \Big),
	\end{align}
and
	\begin{align}
	\label{e:Bound-Xi1W}
	\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[1]}_z(x)&\leq (\vec \Delta^{\rm{start}})_0, \qquad

	\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[1]}_{{ \scriptscriptstyle  R},z}(x)\leq(\vec \Delta^{\rm{start}})_0,\\

	\sum_{x\in\mathbb{Z}^d} |x|^2 \Psi^{\ssc[1],\kappa}_{{ \scriptscriptstyle  R, II},z}(x)&\leq(\vec \Delta^{\rm{start}})_0,\qquad
	\label{e:Bound-Psi1RemIW}
	\sum_{x\in\mathbb{Z}^d} |x-\ve[\kappa]|^2 \Psi^{\ssc[1],\kappa}_{{ \scriptscriptstyle  R, I},z}(x)\leq(\vec \Delta^{\rm{start}})_0+\sum_{x\in\mathbb{Z}^d} \Psi^{\ssc[1],\kappa}_{{ \scriptscriptstyle  R, I},z}(x).
	\end{align}
Further, $\Xi^{\ssc[1],\iota}_z$ is bounded by
	\begin{align}
	\label{e:Bound-XiIota1}
	\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[1],\iota}_z(x)\leq& \frac {g_z}{g^{\iota}_z}(\vec P^\iota)_0,\\
	\label{e:Bound-XiIota1Wa}
	\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[1],\iota}_z(x)\leq&(\vec \Delta^{\iota,{ \scriptscriptstyle  I}})_0,\\
	\label{e:Bound-XiIota1Wb}
	\sum_{x\in\mathbb{Z}^d}|x-\ve[\iota]|^2\Xi^{\ssc[1],\iota}_z(x)\leq &(\vec \Delta^{\iota,{ \scriptscriptstyle  II}})_0.
\end{align}

\label{LemmaBoundXiLTTwo}
Let $0\leq z<z_c$ and $N\geq 2$. Then,
\begin{align}
\label{e:Bound-Xi2}
\sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[N]}_z(x)&\leq \frac {g_z}{g^{\iota}_z} \vec P^T{\bf A}^{N-2}{\vec E}^{\rm{open}}, \quad \sum_{x\in\mathbb{Z}^d}\Xi^{\ssc[N],\iota}_z(x)\leq \frac {g_z}{g^{\iota}_z} (\vec P^{\iota})^T{\bf A}^{N-2}{\vec E}^{\rm{open}},\\
\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[N]}_z(x)\leq& \ N  \left( (\vec \Delta^{\rm{start}})^T{\bf A}^{N-2}{\vec E^{\rm{closed}}}+\vec P^T{\bf A}^{N-2}\vec \Delta^{\rm{end}}\right)\nonumber \\[-5mm]
&\qquad\qquad\qquad+N\1_{\{N> 2\}}\sum_{M=0}^{N-3} \vec P {\bf A}^{M} {\bf C} {\bf A}^{N-3-M}\vec E^{\rm{closed}},
\label{e:Bound-Xi2W}
\\
\sum_{x\in\mathbb{Z}^d}|x|^2\Xi^{\ssc[N],\iota}_z(x)\leq& \ N \left((\vec \Delta^{\iota,{ \scriptscriptstyle  I}})^T{\bf A}^{N-2}{\vec E^{\rm{closed}}}+(\vec P^{\iota})^T{\bf A}^{N-2}\vec \Delta^{\rm{end}}\right)\nonumber \\[-5mm]
&\qquad\qquad\qquad+N\1_{\{N> 2\}}\sum_{M=0}^{N-3} \vec P^\iota {\bf A}^{M} {\bf C} {\bf A}^{N-3-M}\vec E^{\rm{closed}},
\label{e:Bound-XiIota2Wa}
\\
\sum_{x\in\mathbb{Z}^d}|x-\ve[\iota]|^2\Xi^{\ssc[N],\iota}_z(x)\leq& \ N  \left((\vec \Delta^{\iota,{ \scriptscriptstyle  II}})^T{\bf A}^{N-2}{\vec E^{\rm{closed}}}+(\vec P^{\iota})^T{\bf A}^{N-2}\vec \Delta^{\rm{end}}\right)\nonumber \\[-5mm]
&\qquad\qquad\qquad+N\1_{\{N> 2\}}\sum_{M=0}^{N-3} \vec P^\iota {\bf A}^{M} {\bf C} {\bf A}^{N-3-M}\vec E^{\rm{closed}}.
\label{e:Bound-XiIota2Wb}
\end{align}

\label{lemmapercboundXi0minus1}
Let $0\leq z<z_c$. Then,
	\begin{align}
	\label{e:Differencebound-1}
	\Xi^\ssc[0]_{\alpha,z}(0)-\Xi^\ssc[1]_{\alpha,z}(0)\leq&0,\qquad \qquad \Xi^\ssc[0]_{\alpha,z}(\ve[1])-\Xi^\ssc[1]_{\alpha,z}(\ve[1])\leq 0,\\
	\label{e:Differencebound-2}
\Xi^\ssc[1]_{\alpha,z}(0)-\Xi^\ssc[0]_{\alpha,z}(0)\leq & 2dzg^{\iota}_z G_{3,z}(\ve[\iota]),\\
	\Xi^\ssc[1]_{\alpha,z}(\ve[1])-\Xi^\ssc[0]_{\alpha,z}(\ve[1])\leq&
	\frac {g_z^\iota} {g_z} \Big(2\mathscr{B}_{3,\underline 1}(\ve[1],0)+\sum_v \mathscr{T}_{\underline 1,1,1}(\ve[1],v,0)\Big),
\label{e:Differencebound-3}
	\end{align}
and
	\begin{align}
	\label{e:Differencebound-4}
	&\sum_\iota \big(\Psi^{\ssc[1],1}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[1]+\ve[\iota])-\Psi^{\ssc[0],1}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[1]+\ve[\iota])\big) \leq\sum_\iota\sum_w\mathscr{T}_{0,0,\underline 2}(w,\ve[1]+\ve[\iota],0),
\\
	\label{e:Differencebound-5}
	&\sum_\iota \big(\Psi^{\ssc[0],1}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[1]+\ve[\iota])  -\Psi^{\ssc[1],1}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[1]+\ve[\iota]) \big)\leq {\1^{a}}{g^\iota_z}\sum_\iota\mathscr{B}_{2,\underline 2}(\ve[1]+\ve[\iota],0).
	\end{align}
Further,
	\begin{align}
	\sum_\iota \big(\Psi^{\ssc[1],1}_{\alpha,{ \scriptscriptstyle  II},z}&(\ve[\iota])  -\Psi^{\ssc[0],1}_{\alpha,{ \scriptscriptstyle  II},z}(\ve[\iota])\big)\leq
	(2d-1) \Big(2\mathscr{B}_{3,\underline 1}(\ve[1],0)+\sum_v \mathscr{T}_{\underline 1,1,1}(\ve[1],v,0)\Big),
	\label{e:Differencebound-6}\\
	\label{e:Differencebound-7}
	\sum_\iota \big(\Psi^{\ssc[0],1}_{\alpha,{ \scriptscriptstyle  II},z}&(\ve[\iota])  -\Psi^{\ssc[1],1}_{\alpha,{ \scriptscriptstyle  II},z}(\ve[\iota])\big)
	\leq 0.
	\end{align}

In Section \ref{secBoundsDouble} we have already proven the bound on $\Xi^{\ssc[0]}_{z}$.  From $\Xi^{\ssc[0]}_{{ \scriptscriptstyle  R},z}$, we have extracted the contributions in which $0$ and $x$ are connected by a direct bond, see \eqref{e:LA-Split-Def-1}. Considering this, the bounds \eqref{e:Bound-Xi0} and \eqref{e:Bound-Xi0RemW} follow directly.
The only difference between $\Xi^{\ssc[0]}_{{ \scriptscriptstyle  R},z}$ and $\Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, II},z}$ is that $x-\ve[\kappa]\not\in A$ for $\Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, II},z}$.
Since each double connection requires at least two neighbors of $x$ to be part of $A$, the spatial symmetry of the LAs implies that
	\begin{align}
	\sum_{x\in \mathbb{Z}^d} \Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, II},z}(x)=\frac 1 {2d} \sum_{x\in \mathbb{Z}^d, \kappa} \Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, II},z}(x)\leq \frac {2d-2} {2d} \sum_{x\in \mathbb{Z}^d}\Xi^{\ssc[0]}_{{ \scriptscriptstyle  R, II},z}(x),
	\end{align}
which implies \eqref{e:Bound-Psi0RemII} and \eqref{e:Bound-Psi0RemIIW}.

The coefficient $\Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, I},z}(x)$ was created by extracting the shortest contributions with $x=\ve[\kappa]$ and $x$'s that are neighbors of $\ve[\kappa]$. The contribution of the remaining $(2d-1)$ neighbors of the origin is bounded using $\mathscr{B}_{\underline 1,3}(\ve[1],0)$. For all other $x$, i.e., those with $|x|>1$, we use $\Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, II},z}(x)\leq \Psi^{\ssc[0],\kappa}_{{ \scriptscriptstyle  R, I},z}(x)$ to conclude the bounds stated in \eqref{e:Bound-Psi0RemI}.

In \eqref{e:Bound-Psi0RemIW}, we bound the contribution due to all neighbors of origin by the first term.
The contribution due to all other $x$ are bounded by the second term. Regarding the neighbors $x=\ve[\iota]$ of the origin, with $\iota\in\{\pm1,\dots,\pm d\}$, we note that
	\begin{align}
	|x-\ve[\kappa]|^2=|\ve[\iota]-\ve[\kappa]|^2=
	\begin{cases}
	2 & \text{ for~} |\iota|\neq |\kappa|,\\
	4 & \text{ for } \iota=-\kappa,\\
	0 & \text{ for } \iota= \kappa.
	\end{cases}
	\end{align}
Summing over $\iota$ creates the stated factor $4d$.
For the other $x$, we know that any path to $x$ contains at least two bonds.
To be able to use a symmetry argument, we ignore that we extracted terms and as well as the condition $x-\ve[\kappa]\not\in A$, to obtain the simple bound
	\begin{align}
	(2dz)^2g_z (D^{\star 2} \star \tilde G_z)(x)  \bar G_z(x)
	\end{align}
Then, we use $|x-\ve[\kappa]|^2=(|x|^2 -2x_\kappa+1)$ and that the term involving $-2x_\kappa$ sums to zero by symmetry, to obtain
	\begin{align}
	\label{e:Bound-Psi0RemIIW-proofLine}
	\sum_x |x-\ve[\kappa]|^2 (2dz)^2g_z (D^{\star 2} \star \tilde G_z)(x)  \bar G_z(x)=\sum_x (|x|^2+1 ) (2dz)^2g_z (D^{\star 2} \star \tilde G_z)(x)  \bar G_z(x),
	\end{align}
which is the second term in \eqref{e:Bound-Psi0RemIW}.
This proves \eqref{e:Bound-Psi0RemIW}, and completes the proof of Lemma \ref{BoundNZero-Xi}.

By definition,
	\begin{align}
	\Xi^{\ssc[0],\iota}_z(x)= \frac {1}{g_z}    \sum_{A\colon 0,x,\ve[\iota]\in A} z^{|A|}\1_{\{0 \stackrel{A}{\Longleftrightarrow}  x\}}.
	\end{align}
For LTs, this simplifies to
	\begin{align}
	\Xi^{\ssc[0],\iota}_z(x)= \frac {\delta_{0,x}}{g_z}  \bar G_z(\ve[\iota])=\delta_{0,x}G_z(\ve[\iota]).
	\end{align}
For LAs we recall that we have bounded such animals already between \eqref{e:split-LA-sausage-Gbar} and \eqref{e:split-LA-sausage-second}.




We improve these bounds by using {\em repulsive diagrams} (recall Section \ref{secBoundsRepdia}) and by considering four cases for the point $u$, where $u$ is the summand appearing in \eqref{e:split-LA-sausage-Gbar}, thus yielding the bound $\alpha_{1,1}$ (see \eqref{e:BoundNZero-XiIota-alpha}). Let us explain the four cases for $u$:\\
(a) For $u=0$, the diagram is given by a double connection from $0$ to $x$ and a simple path from $0$ to $\ve[\iota]$ that we bound by
	\begin{align}
	G_z(\ve[\iota])+ \frac {1}{g_z} \tilde G_z(\ve[\iota]) \sum_{x\neq 0} \mathscr{D}_{1}(x,0).
	\end{align}
The first term is given explicitly in \eqref{e:Bound-XiIota0} and the second term corresponds to the first term of $\alpha_{1,1}$.\\
(b) For $u=\ve[\iota]$, the point $\ve[\iota]$ is on the double connection between $0$ and $x$.
For $x=\ve[\iota]$, we have a simple double connection to $\ve[\iota]$, otherwise a repulsive triangle, as stated in the second and third term of $\alpha_{1,1}$.\\
(c) In the contributions in which $u=x\not\in \{0,\ve[\iota]\}$ we find a double connection between $0$ and $x$, bounded by $\mathscr{D}_{1}(x,0)$  and a connection from $x$ to $\ve[\iota]$, bounded by $\tilde G_{m,z}(x-\ve[\iota])$. We improve this bound slightly using the parity of the lattice:
If $0$ and $x$ are directly connected, the length of the connection between $x$ to $\ve[\iota]$ is at least $2$.\\
(d) In the remaining contributions, we have that $u\neq \{0,x,\ve[\iota]\}$, so that these LAs can be bounded by
	\begin{align}
 	\sum_{u}\mathscr{B}_{1,1}(u,\ve[\iota])  \sup_{u} \sum_{x}\mathscr{B}_{1,1}(x,u),
	\end{align}
which corresponds to the last term of $\alpha_{1,1}$. This completes the proof of \eqref{e:Bound-XiIota0}.

The diagrams with the additional weights $|x|^2$ and $|x-\ve[\iota]|^2$ are bounded in a similar manner. As the numerical bounds, using the bootstrap function $f_3$, require a $G_z$ to carry the spatial weight, we express the bounds using two-point functions instead of repulsive diagrams. For the weight $|x-\ve[\iota]|^2$, two additional steps are made: Firstly, for $u=0\neq x$ we first split the weights using symmetry, as shown in \eqref{e:Bound-Psi0RemIIW-proofLine}, and then bound the two arising terms. This leads to the first line of $\gamma_1$ in \eqref{e:BoundNZero-XiIota-gamma}. Secondly, for $u\neq \{0,\ve[\iota],x\}$, we use that $|x-\ve[\iota]|^2\leq 2(|x|^2+1)$, see \cite[(2.24)]{FitHof13b}, and bound the arising terms individually. This completes the proofs of \eqref{e:Bound-XiIota0Wa} and \eqref{e:Bound-XiIota0Wb}.


For the bounds on $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, I},z}$ and $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, II},z}$ stated in \eqref{e:Bound-XiIota0RemI}-\eqref{e:Bound-XiIota0RemII}, we review which terms have been extracted from $\Xi^{\ssc[0],\iota}_z(x)$ to yield $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, I},z}$ and $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, II},z}$. For $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, II},z}(x)$, the LAs in which $x$ is directly connected to the origin have been removed. For this reason, in $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, II},z}$ all paths from $0$ to $x$ have a length of at least $2$ instead of $1$. This is  expressed by the subscripts $n$ of $\alpha_{n,m}$ and $\beta_{n}$. To obtain $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, I},z}(x)$ from  $\Xi^{\ssc[0],\iota}_z(x)$, we have extracted all LAs in which $x$ is directly connected to $\ve[\iota]$. This means that in $\Xi^{\ssc[0],\iota}_{{ \scriptscriptstyle  R, I},z}(x)$, the path from $\ve[\iota]$ to $x$ in contributing LAs have length at least $2$.
The bounds \eqref{e:Bound-XiIota0RemI} and \eqref{e:Bound-XiIota0RemII} are created by repeating the consideration of cases for $u$, as given above for the bound on bound $\Xi^{\ssc[0],\iota}_z(x)$, while keeping these additional restrictions.

We continue with the bounds on $\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}$ and $\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  II},z}$ in \eqref{e:Bound-XiIotaAlphaI}--\eqref{e:Bound-XiIotaAlphaIIWb}. Note that for LTs, most of these terms are zero due to the lack of double connections, so we restrict to LAs. Recall \eqref{e:split-LTs-N0}, as well as \eqref{e:split-LTs-N0a}--\eqref{e:split-LTs-N0b}.

By their definitions in \eqref{e:LA-Split-Def-XiIotaAlphaa} and \eqref{e:LA-Split-Def-XiIotaAlphab},
	\begin{align}
	\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[\iota])= &  \frac {\1^{a}}{g_z} \sum_{A\colon 0,\ve[\iota]\in A} z^{|A|}\1_{\{0 \stackrel{A}{\Longleftrightarrow}  \ve[\iota]\}}
	\leq \frac {\1^{a}}{g_z}\mathscr{D}_{1}(\ve[\iota]),\\
	\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  II},z}(0)=&\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}(0)=\frac 1 {g_z} \bar G_z(\ve[\iota])= G_z(\ve[\iota]),
	\end{align}
which proves \eqref{e:Bound-XiIotaAlphaI}. To obtain the bound in \eqref{e:Bound-XiIotaAlphaIWa}, we again use \eqref{e:LA-Split-Def-XiIotaAlphaa}, and remark that, for $x\neq 0$ with $|x-\ve[\iota]|^2=1$,
we can write $x=\ve[\kappa]+\ve[\iota]$ with $\kappa\neq -\iota$ to get
	\begin{align}
	\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[\kappa]+\ve[\iota])=&\frac {1}{g_z} \sum_{A\colon 0,\ve[\kappa]+\ve[\iota],\ve[\iota]\in A} z^{|A|}\1_{\{0 \stackrel{A}{\Longleftrightarrow}  \ve[\kappa]+\ve[\iota]\}} \1_{\{d_A(\ve[\iota],\ve[\kappa]+\ve[\iota])=1\}}.
	\end{align}
Thus, $\ve[\kappa]+\ve[\iota]$ and $\ve[\iota]$ are directly connected in the LA. We distinguish between the case where $\ve[\iota]$ is on the double connection or not to obtain
	\begin{align}
	\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}(\ve[\kappa]+\ve[\iota])\leq&\frac {\1^{a}}{g_z}\mathscr{T}_{1,\underline 1,2}(\ve[\iota],\ve[\kappa]+\ve[\iota],0)
	+\frac {zg_z^\iota \1^{a}}{g_z}(1-\delta_{\kappa,-\iota})\mathscr{B}_{2,2}(\ve[\iota]+\ve[\kappa],0).
	\end{align}

Summing over all neighbors $\ve[\kappa]+\ve[\iota]$ of $\ve[\iota]$, and also using that the contribution of $\kappa=-\iota$ is $\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  I},z}(0)=G_z(\ve[\iota])$, proves \eqref{e:Bound-XiIotaAlphaIWa}.


For $\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  II},z}(\ve[\kappa])$, we recall \eqref{e:LA-Split-Def-XiIotaAlphab}, and consider $\kappa\neq \iota$, distinguish between the cases where $\ve[\iota]$ is part of the double connection from $0$ to $\ve[\kappa]$ or not. For this, let $u$ be the first point that any path between $0$ and $\ve[\iota]$, and the path between $\ve[\kappa]$ and $\ve[\iota]$, share.
We split between $u=0, \ve[\kappa],\ve[\iota]$ and $u\not\in \{0,\ve[\kappa], \ve[\iota]\}$, to obtain
	\begin{align}
    	\Xi^{\ssc[0],\iota}_{\alpha,{ \scriptscriptstyle  II},z}(\ve[\kappa])=&\frac {\1^{a}}{g_z}\sum_{A\colon 0,\ve[\kappa],\ve[\iota]\in A} z^{|A|}\1_{\{0 \stackrel{A}{\Longleftrightarrow}  \ve[\kappa]\}} \1_{\{d_A(0,\ve[\kappa])=1\}}\\
    	\leq & z \1^{a} G_{3,z}(\ve[\kappa]) \big(\tilde G_{1,z}(\ve[\iota])+\tilde G_{2,z}(\ve[\kappa]-\ve[\iota])\big)\nonumber\\
    	&+\frac {\1^{a}}{g_z}\mathscr{T}_{1,2,\underline 1} (\ve[\iota],\ve[\kappa],0)+z \frac{g_z^\iota}{g_z} \1^{a} \sup_{x\neq 0}\tilde G_{1,z}(x)\sum_{u}\mathscr{B}_{1,1}(u,\ve[\kappa]).\nonumber
	\end{align}



Summing this over all neighbors $\ve[\kappa]$ of the origin, and using that the contribution for $\kappa=\iota$ can be bounded by $\frac {\1^{a}}{g_z}\mathscr{D}_{1}(\ve[\iota])$, proves \eqref{e:Bound-XiIotaAlphaIIWb}.




For the bounds on $\Pi^{\ssc[0],\iota,\kappa}_{z}, \Pi^{\ssc[0],\iota,\kappa}_{\alpha,z}$  and  $\Pi^{\ssc[0],\iota,\kappa}_{{ \scriptscriptstyle  R},z}$ stated in \eqref{e:Bound-Pi0AlphaI}--\eqref{e:Bound-Pi0RemIW}, it is useful to write out the definition of $\Pi^{\ssc[0],\iota,\kappa}_{z}$ in \eqref{e:defPiNanimal}, and simplify it for the special case $N=0$. This leads to
	\begin{align}
	\Pi^{\ssc[0],\iota,\kappa}_z(x)&=
	\sum_{A\colon 0,x\in A} z^{|A|+1}\1_{\{0 \stackrel{A}{\Longleftrightarrow}  x\}}
	\big(\1_{\{\ve[\iota]\in A_0^\omega\}}+ \1_{\{|\omega|=0\}}\1_{\{x\neq 0\}}\1_{\{x-\ve[\kappa]=\ve[\iota]\}}\big)\1_{\{x-\ve[\kappa]\not\in A\}}.
	\end{align}
Using the split $\Pi^{\ssc[0],\iota,\kappa}_{\alpha,z}$ (see \eqref{e:LA-Split-Def-1a}), we extract from this the contributions where $x=\ve[\iota]$, as well as those with
$x=\ve[\iota]+\ve[\kappa]$ in which the edge $(\ve[\iota],\ve[\iota]+\ve[\kappa])$ is in the LA. For $x=\ve[\iota]$, we see that
	\begin{align}
	\label{e:no-problems-Xi-Pi}
	\Pi^{\ssc[0],\iota,\kappa}_{\alpha,z}(\ve[\iota])&=\Pi^{\ssc[0],\iota,\kappa}_z(\ve[\iota])= \1^{a}\sum_{A\colon 0,\ve[\iota]\in A} z^{|A|+1}\1_{\{0 \stackrel{A}{\Longleftrightarrow}  \ve[\iota]\}}\1_{\{\ve[\iota]-\ve[\kappa]\not\in A\}}\nonumber\\
	&\leq \1^{a} (1-\delta_{\iota,-\kappa}) z \mathscr{D}_{1}(\ve[\iota]),
	\end{align}
as the LAs contain a simple double connection to a neighbor of the origin. Summing this over $\kappa$ proves \eqref{e:Bound-Pi0AlphaI}.
The bounds \eqref{e:Bound-Pi0RemI} and \eqref{e:Bound-Pi0RemIW} basically follow from the fact that $\Pi^{\ssc[0],\iota,\kappa}_z(x)\leq zg_z\Xi^{\ssc[0],\iota}_z(x)$, see \eqref{e:XidominatespsiImproved}.
To understand \eqref{e:Bound-Pi0RemI} we compare the bound with \eqref{e:Bound-XiIota0}.
When summing over $\iota$ for $x=0$, $\iota=-\kappa$ does not contribute explaining the factor $(2d-1)$.
Further, we have extracted the case that $x=\ve[\iota]$, thus we can us $\alpha_{1,1}$ instead of $\alpha_{1,0}$ for this bound.

For \eqref{e:Bound-Pi0RemIW}, we need to redistribute the weights. We write
	\begin{align} 
	\label{e:Pi(0)-bd}
	\sum_{x,\iota,\kappa}|x-\ve[\iota]|^2\Pi^{\ssc[0],\iota,\kappa}_{{ \scriptscriptstyle  R},z}(x+\ve[\kappa])
	&=\sum_{\iota,\kappa}\sum_{x\neq \ve[\iota]}|x-\ve[\iota]-\ve[\kappa]|^2\Pi^{\ssc[0],\iota,\kappa}_{{ \scriptscriptstyle  R},z}(x)\\
	&\leq\sum_{\iota,\kappa} |\ve[\iota]+\ve[\kappa]|^2\Pi^{\ssc[0],\iota,\kappa}_{{ \scriptscriptstyle  R},z}(0)\nonumber\\
	&\qquad+\1^{a} zg_z
\sum_{\iota,\kappa}\sum_{x\not\in\{0,\ve[\iota]\}}[|x-\ve[\iota]|^2+1-2(x_\kappa-\delta_{\iota,\kappa})]\Xi^{\ssc[0],\iota}_z(x),\nonumber
	 \end{align}
since $\Pi^{\ssc[0],\iota,\kappa}_z(x)\leq zg_z\Xi^{\ssc[0],\iota}_z(x)$. The first contribution is bounded by $2(2d)^2zg_z G_z(\ve[\iota])$. We use \eqref{e:Bound-XiIota0Wb}
for the $|x-\ve[\iota]|^2$ contribution.
We further use \eqref{e:Bound-XiIota0} (without the term created by $x\in\{0,\ve[\iota]\}$) to obtain a bound $(2d)^2zg_z\alpha_{1,1}$ on the contribution due to $+1$. Finally, $\sum_{\iota} \Xi^{\ssc[0],\iota}_z(x)$ is symmetric, so that the $x_\kappa$ contribution vanishes, while the $\delta_{\iota,\kappa}$ contribution gives $2\sum_{\iota, x\not\in\{0,\ve[\iota]\}} \Xi^{\ssc[0],\iota}_z(x)$, which can be taken together with the $+1$ contribution using \eqref{e:Bound-XiIota0}.

\label{pDominatespTreeNOne}
For all $x\in\mathbb{Z}^d$, $\iota$ and $0\leq z\leq z_c$,
	\begin{eqnarray}
	\label{e:PnDominatesXiNOne}
	\Xi^{\ssc[1]}_{z}(x)&\leq& \frac {g_z}{g^{\iota}_z} P^{\ssc[1],0}_{z}(x,x),\\
	\label{e:PnDominatesXiIotaNOne}
	\Xi^{\ssc[1],\iota}_{z}(x)&\leq& \frac {g_z}{g^{\iota}_z} P^{\ssc[1],\iota,0}_{z}(x,x).
	\end{eqnarray}

\label{pDominatespTree}
For all $x\in\mathbb{Z}^d$, $\iota$ and $0\leq z\leq z_c$, and $N\geq 2$
	\begin{eqnarray}
	\label{e:PnDominatesXiNTwo}
	\Xi^{\ssc[N]}_{z}(x)&\leq& \frac {g^{\iota}_z}{g_z} \sum_{u,v,l} P^{\ssc[N-1],l}(u,v) A^{l,0}(u,v,x,x),\\
	\label{e:PnDominatesXiNTwoWeight}
	\Xi^{\ssc[N]}_{z}(x,\Delta_N)&\leq&  \sum_{u,v,l} P^{\ssc[N-1],l}(u,v) \Delta^{{\rm end},l}(u,v,x,x),\\
	\label{e:PnDominatesXiNTwoPrime}
	\Xi^{\ssc[N]}_{z}(x,\Delta_1)&\leq& \sum_{u,v,l} \Delta^{{\rm start},l} (x_1,v) Q^{\ssc[N-1],l}(u,v;x).
	\end{eqnarray}
Further, for  $N,M\geq 1$,
	\begin{align}
	\label{e:PnDominatesXiN}
	\Xi^{\ssc[N+M+1]}_{z}(x,\Delta_{N+1})&\leq& \sum_{u,v,w,y}\sum_{l,m}P^{\ssc[N],l}(u,w)C^{l,m}(u,v,w,y)Q^{\ssc[M],m}(w,y;x).
	\end{align}
The same bounds hold for $\Xi^{\ssc[N],\iota}$, when $P^{\ssc[N-1],l}$ and $\Delta^{{\rm start},l} $
 are replaced by $P^{\ssc[N-1],\iota,l}$ and $\Delta^{{\rm iota},{ \scriptscriptstyle  I},l} $ or $\Delta^{{\rm iota},{ \scriptscriptstyle  II},l}$, respectively.

\label{lem-LBzI}
Let $z_I$ satisfy
	\begin{equation} 
	z_I g_{z_I}^\iota =\frac{1}{2d-1}.
	 \end{equation}
Then, $z_I\geq (2d-1)^{-1}{\mathrm e}^{-1}$.

\label{lemmaAnalysisLABound}
The number of $n$-bond LAs that contain the origin is bounded above by
\begin{align}
\label{e:lemmaAnalysisLABound-statement}
2d (2d-1)^{n-1}\frac {(n+1)^{n}}{(n+1)!}.
\end{align}

We use Lemma \ref{lemmaAnalysisLABound} to show that $z_I\geq (2d-1)^{-1}{\mathrm e}^{-1}$.
For this, we bound $g_z$ using \eqref{e:lemmaAnalysisLABound-statement}, as
	\begin{align}
	\label{e:LTAbstractBound}
	g_z&\leq 1 + \sum_{n=1}^{\infty}z^n (2d)(2d-1)^{n-1} \frac {(n+1)^{n}}{(n+1)!}.
	\end{align}
We note that
	\begin{eqnarray}
	\label{e:LTAbstractBound-tool}
	\sum_{n=1}^\infty\frac {n^{n-1}}{n!}{\mathrm e}^{-n}=1,
	\end{eqnarray}
since the summand in \eqref{e:LTAbstractBound-tool} equals the probability that the total progeny of a branching process with Poisson offspring distribution with parameter one equals $n$, and the sum of these probabilities equals 1, since the tree is a.s.\ finite.
We obtain for $z \leq((2d-1){\mathrm e})^{-1}$ that
	\begin{align}
	g_z\leq&  1 + \sum_{n=2}^{\infty}z^{n-1} (2d)(2d-1)^{n-2} \frac {n^{n-1}}{n!}\leq 1 + \sum_{n=2}^{\infty}\frac{(2d)(2d-1)^{n-2}}{(2d-1)^{n-1}{\mathrm e}^{n-1}} \frac {n^{n-1}}{n!}\nonumber\\
	=& 1 + \frac {2d {\mathrm e}}{(2d-1)}\sum_{n=2}^{\infty} \frac {n^{n-1}}{n!} {\mathrm e}^{-n}=1 + \frac {2d {\mathrm e}}{(2d-1)} \left( 1 - \frac {1}{{\mathrm e}}\right)= {\mathrm e}+ \frac {{\mathrm e}-1}{2d-1}.
	\end{align}
Since $g^{\iota}_z\leq g_z$ this is also a bound for $g^{\iota}_z$. We can improve this bound on $g^{\iota}_z$ by using the condition that $\ve[\iota]$ is not part of the tree/animal. A non-trivial LT/LA contains at least one edge connecting the origin to a neighboring point.
Therefore, at least at $1$ out of $2d$ LTs/LAs counted in $g_z$ does not contribute to $g^{\iota}_z$. We conclude that
	\begin{eqnarray}
	\label{e:gjgzrelation-Initial}
	g^{\iota}_z\leq 1+\frac {2d-1}{2d}(g_z-1)=1+\frac {(2d-1)({\mathrm e}-1)}{2d} \left(1+\frac 1 {2d-1}\right)={\mathrm e},
	\end{eqnarray}
and thus, for all $z\leq z_I$,
	\begin{align}
    \label{e:Bound-Initial-f1}
	(2d-1)g^{\iota}_z z&\leq 1,\ &(2d-1)\bar \alpha_z =(2d-1)g_z z\leq 1+ \frac {1-{\mathrm e}^{-1}}{2d-1},
	\end{align}
as well as, by the definition of $z_I$ in \eqref{e:DefinitionOfzI},
	\begin{align}
	1=(2d-1)g^\iota_{z_I} {z_I}\leq(2d-1) {\mathrm e} z_I.
	\end{align}
This implies that $z_I\geq (2d-1)^{-1}{\mathrm e}^{-1}$.

The proof of \cite[Lemma 3.1]{HarSla90b} uses a similar bound as stated in \eqref{e:lemmaAnalysisLABound-statement} in Lemma \ref{lemmaAnalysisLABound}, but contains an error.
Namely it is used that there are $(n+1)^{n}/(n+1)!$ abstract unlabeled rooted trees with $n$ edges. However, while Cayley's theorem states that there are $(n+1)^{n}$ labeled rooted trees, the removal of the labels does not create a factor $1/(n+1)!$ as stated. Indeed, there are less than $(n+1)!$ ways to label an abstract tree, e.g., for a tree with two edges there are only $3$ different ways to label the tree as the only difference is the label of the vertex that is part of two edges.

To prove the bound stated in \eqref{e:lemmaAnalysisLABound-statement} we first use the techniques of \cite[Sections 2 and 5]{BorChaHofSla99} to show the lemma only for LTs. Then, we adapt the arguments to LAs.

We begin by defining a non-backtracking branching random walk with Poisson offspring distribution. Abstract trees are the family trees of a critical branching process with Poisson offspring distribution. In more detail, we begin with a single individual having $\xi$ offspring, where $\xi$ is a Poisson random variable of mean $1$, i.e., $\prob(\xi=m)=({\mathrm e} m!)^{-1}$. Each of the offspring then independently has offspring of its own with the same critical Poisson distribution.
We denote by $|\mathcal{T}|$ the number of bonds of the tree $\mathcal{T}$. For an abstract rooted tree $\mathcal{T}$,
with the $i$th individual having $\xi_i$ offspring, this associates to $\mathcal{T}$ the weight
	\begin{align}
	\prob(\mathcal{T})={\mathrm e}^{-(|\mathcal{T}|+1)}\prod_{i\in \mathcal{T}}\frac 1 {\xi_i!}.
	\end{align}
We define an embedding of $\varphi$ of $\mathcal{T}$ into $\mathbb{Z}^d$ to be a mapping of the vertices of $\mathcal{T}$ into $\mathbb{Z}^d$, such that the root is mapped to the origin and adjacent vertices in the tree are mapped to nearest-neighbors in $\mathbb{Z}^d$. Further, we restrict to embeddings in which the children are not mapped to the location of the grandparents. We define the pair $(\mathcal{T},\varphi)$ to be a non-backtracking branching random walk with Poisson offspring distribution (Poisson-NBBRW). Given an abstract tree $\mathcal{T}$ with $n$ bonds, there are $2d (2d-1)^{n-1}$ possible embeddings $\varphi$ of $\mathcal{T}$. The Poisson-NBBRW measure is given by
	\begin{align}
	\label{e:Analysis-P-measure}
		\prob(\mathcal{T},\varphi)=\frac {1}{2d(2d-1)^{|\mathcal{T}|-1}} \prob(\mathcal{T}) =\frac {1}{2d(2d-1)^{|\mathcal{T}|-1}}{\mathrm e}^{-(|\mathcal{T}|+1)}\prod_{i\in \mathcal{T}}\frac 1 {\xi_i!}.
	\end{align}
for all $\mathcal{T}$ and $\varphi$.	We define $\Ibold^{ \scriptscriptstyle  (t)}(\mathcal{T},\varphi)$ to be the indicator that the embedding $\varphi$ of $\mathcal{T}$ is a LT, i.e., $\varphi\colon \mathcal{T}\mapsto \mathbb{Z}^d$ is injective. For a LT $T$, we write $T=\varphi(\mathcal{T})$ if the embedding $\varphi$ of $\mathcal{T}$ equals $T$.
For abstract trees with $n$ bonds, we define the measure
	\begin{align}
	{\mathbb Q}^{ \scriptscriptstyle  (t)}_n(\mathcal{T},\varphi)=\frac  1 {Z^{ \scriptscriptstyle  (t)}_n} \prob(\mathcal{T},\varphi)\Ibold^{ \scriptscriptstyle  (t)}(\mathcal{T},\varphi),
	\end{align}
with normalization
	\begin{align}
	Z^{ \scriptscriptstyle  (t)}_n=\sum_{(\mathcal{T},\varphi)\colon |\mathcal{T}|=n}\prob(\mathcal{T},\varphi)\Ibold^{ \scriptscriptstyle  (t)}(\mathcal{T},\varphi).
	\end{align}
We prove that the number of $n$-bond LTs that contain the origin is given by
	\begin{align}
	\label{e:Analysis-LT-Normalizer-Solved}
	t^{ \scriptscriptstyle  (t)}_n(0) = Z^{ \scriptscriptstyle  (t)}_n {\mathrm e}^{n+1}2d(2d-1)^{n-1},
	\end{align}
which is equivalent to
	\begin{equation} 
	\label{e:Analysis-LT-Normalizer-Solved-2}
	Z^{ \scriptscriptstyle  (t)}_n=t^{ \scriptscriptstyle  (t)}_n(0) {\mathrm e}^{-(n+1)}(2d)^{-1}(2d-1)^{-(n-1)}.
	 \end{equation}
To do that, we show that, for each $n$-bond LT $T$,
	\begin{align}
	\label{e:Analysis-Q-is-Uniform-LT-measure}
	\sum_{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=T} {\mathbb Q}^{ \scriptscriptstyle  (t)}_n(\mathcal{T},\varphi)=\frac {{\mathrm e}^{-(n+1)}}{2d(2d-1)^{n-1}},
	\end{align}
which implies that the measure ${\mathbb Q}^{ \scriptscriptstyle  (t)}_n$ corresponds to the uniform measure on all $n$-bond LTs and thus implies \eqref{e:Analysis-LT-Normalizer-Solved-2}, and thus \eqref{e:Analysis-LT-Normalizer-Solved}.



From \eqref{e:Analysis-P-measure} we conclude that, for all $T$ with $|T|=n$,
	\begin{align}
	\sum_{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=T} \prob(\mathcal{T},\varphi) = \frac {{\mathrm e}^{-(n+1)}}{2d(2d-1)^{n-1}}
	\sum_{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=T} \prod_{i\in \mathcal{T}}\frac 1 {\xi_i!}.
	\end{align}

We continue by proving that, for any LT $T$,
	\begin{align}
	\label{e:Analysis-LT-Poisson-isOne}
	\sum_{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=T} \prod_{i\in \mathcal{T}}\frac 1 {\xi_i!}=1.
	\end{align}
Let $d_0$ be the degree of $0$ in $T$, and given non-zero $x\in T$, let $d_x$ be the degree of $x$ in $T$
minus $1$. The set $\{d_x\colon x\in T\}$ must be equal to the set of $\xi_i$ for any $\mathcal{T}$ that can be mapped to $T$.
Defining $\nu(T)=\#\{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=T\}$, \eqref{e:Analysis-LT-Poisson-isOne} is therefore equivalent to
	\begin{align}
	\label{e:Analysis-LT-Poisson-isOne-Tool}
	\nu(T)=\prod_{x\in T}d_x!.
	\end{align}
We prove \eqref{e:Analysis-LT-Poisson-isOne-Tool} by induction on the number $N$ of generations of $T$. By this, we mean the length of the longest self-avoiding path in $T$, starting from the origin. The identity \eqref{e:Analysis-LT-Poisson-isOne-Tool} clearly holds for $N=0$. Our induction hypothesis is that \eqref{e:Analysis-LT-Poisson-isOne-Tool} holds if there are $N-1$ or fewer generations. Suppose $T$ has $N$ generations, let $T_1,\dots,T_{d_0}$ denote the LTs resulting from deleting from $T$ all bonds incident on the origin. We regard each $T_a$ as rooted at the neighbor of the origin in the corresponding deleted bond. It suffices to show that $\nu(T)=b_0!\prod_{a=1}^{d_0}\nu(T_a)$, since each $T_a$ has fewer than $N$ generations. To prove this, we note that each $(\mathcal{T},\varphi)$ with $\varphi(\mathcal{T})=T$ induces a Poisson-NBBRW $(\mathcal{T}_a,\varphi_a)$ such that $\varphi_a(\mathcal{T}_a)=T_a$. This correspondence is $d_0!$ to $1$, since $(\mathcal{T},\varphi)$ is determined by the set of $(\mathcal{T}_a,\varphi_a)$, up to permutations of the branches of $\mathcal{T}$ at its root. This proves $\nu(T)=d_0!\prod_{a=1}^{d_0}\nu(T_a)$.



We finally complete the proof of the lemma for LTs. We rearrange \eqref{e:Analysis-LT-Normalizer-Solved} and use \eqref{e:Analysis-P-measure} to obtain
	\begin{align}
	t^{ \scriptscriptstyle  (t)}_n(0) =& 2d(2d-1)^{n-1}{\mathrm e}^{n+1} \sum_{T\colon |T|=n}\sum_{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=T} \prob(\mathcal{T},\varphi)\nonumber\\
	=& {\mathrm e}^{n+1} \sum_{T\colon |T|=n} \sum_{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=T} \prob(\mathcal{T})
	\leq  {\mathrm e}^{n+1}   \sum_{(\mathcal{T},\varphi)\colon |\mathcal{T}|=n} \prob(\mathcal{T}).
	\label{e:Analysis-LT-Lemma-nextto-laststep}
	\end{align}
Since there are $2d (2d-1)^{n-1}$ embeddings $\varphi$, we then know that
	\begin{align}
	t^{ \scriptscriptstyle  (t)}_n(0) \leq & 2d (2d-1)^{n-1} {\mathrm e}^{n+1} \sum_{\mathcal{T}\colon |\mathcal{T}|=n} \prob(\mathcal{T})\nonumber\\
	= &2d(2d-1)^{n-1}{\mathrm e}^{n+1}       \prob(|\mathcal{T}|=n).
	\label{e:Analysis-LT-Lemma-laststep}
	\end{align}
The probability distribution of the total number of bonds of a Poisson branching process is given by $\prob(|\mathcal{T}|=n)={\mathrm e}^{-(n+1)} (n+1)^{n}/(n+1)!$
(as this is the number of vertices, also called the total progeny, minus 1). We insert this into \eqref{e:Analysis-LT-Lemma-laststep} and obtain the claimed bound for LTs.
\medskip

The claim for LAs is obtained using similar ideas, but requires some adaptations as LAs can contain loops. The main difficulty is to obtain a relation similar to \eqref{e:Analysis-LT-Poisson-isOne-Tool}.

We define $\Ibold^{ \scriptscriptstyle  (a)}(\mathcal{T},\varphi)$ to be the indicator for the event that
\begin{enumerate}[(1)]
\item no two bonds of the abstract tree $\mathcal{T}$ are mapped to the same bond in $\mathbb{Z}^d$ by $\varphi$,
\item for all $i\in\mathcal{T}$ either $\xi_i=0$ or the following two conditions hold:
  \begin{enumerate}
\item  there exist no $j\in\mathcal{T}\setminus\{i\}$, such that $\varphi(i)=\varphi(j), \xi_j>0$ and ${\rm height}(j)={\rm height}(i)$,
\item  there exist no $j\in\mathcal{T}\setminus\{i\}$, such that $\varphi(i)=\varphi(j)$ and ${\rm height}(j)<{\rm height}(i)$,
\end{enumerate}
where the height of a individual point $a\in\mathcal{T}$ is intrinsic distance of $a$ to the root in $\mathcal{T}$.
\end{enumerate}
For a Poisson-NBBRW $(\mathcal{T}_a,\varphi_a)$ (1) guarantees that each bond is only used once by the process and (2) is the condition that whenever a point is visited by multiple individuals then only the first of them can have offspring. Thus, (1) and (2) together imply that the image $\varphi(\mathcal{T})$ is a LA. Here, for a LA $A$, we write $A=\varphi(\mathcal{T})$ if the embedding $\varphi$ of $\mathcal{T}$ equals $A$.


Now we proceed as for the LT by defining
	\begin{align}
	{\mathbb Q}^{ \scriptscriptstyle  (a)}_n(\mathcal{T},\varphi)=&\frac  1 {Z^{ \scriptscriptstyle  (a)}_n} \prob(\mathcal{T},\varphi)\Ibold^{ \scriptscriptstyle  (a)}(\mathcal{T},\varphi),
	\end{align}
where
	\begin{equation} 
	Z^{ \scriptscriptstyle  (a)}_n=\sum_{(\mathcal{T},\varphi)\colon |\mathcal{T}|=n}\prob(\mathcal{T},\varphi)\Ibold^{ \scriptscriptstyle  (a)}(\mathcal{T},\varphi).
	 \end{equation}
We next prove that the number of $n$-bond LAs containing the origin is given by
	\begin{align}
	\label{e:Analysis-LA-Normalizer-Solved}
	t^{ \scriptscriptstyle  (a)}_n(0) = Z^{ \scriptscriptstyle  (a)}_n {\mathrm e}^{n+1}2d(2d-1)^{n-1}.
	\end{align}
This is analogous to the proof for LT in \eqref{e:Analysis-LT-Normalizer-Solved}, which the exception of the proof that
	\begin{align}
	\label{e:Analysis-LA-Poisson-isOne}
	\sum_{(\mathcal{T},\varphi)\colon \varphi(\mathcal{T})=A} \Ibold^{ \scriptscriptstyle  (a)}(\mathcal{T},\varphi) \prod_{i\in \mathcal{T}}\frac 1 {\xi_i!}=1.
	\end{align}
We now explain how to adapt the argument so as to obtain \eqref{e:Analysis-LA-Poisson-isOne}. To prove this we define $d_x$ such that it corresponds to the number of offspring of the Poisson branching process. In contrast to the LT case, for LAs it can happen that $\varphi$ maps multiple individuals of $\mathcal{T}$ to $x$. Therefore, it is not obvious how to choose $d_x$ such that $(\xi_i)_i$ and $(d_x)_x$ are equivalent.

For a LA $A$, and two vertices $x,y\in A$, we define $d_{A}(x,y)$ to be the intrinsic distance between $x$ and $y$, and call the distance $d_A(0,x)$ the {\em age} of $x$.                                                                                                                                                                                                                                                                                             
For $N\in\Nbold$, we call the set of all vertices with age $N$ the {\em generation} $N$. We define an exploration process, that we use to define $(d_x)_x$, as follows:

\begin{enumerate}[1)]
\item We define $d_0$ to be the degree of $0$ in $A$;
\item We define $S$ to be the set of all vertices directly connected to the origin in $A$;
\item We define $B\subset A$ to be the subset of all bonds in $A$ that do not contain the origin;
\item Let $N$ be the age of the youngest vertex in $S$;
\item For the unique $x$ in the $N$th generation with the lowest lexicographic order:
\begin{enumerate}[i)]
\item we define $d_x$ to be the degree of $x$ in $B$;
\item we update $S$ by adding the endpoints of the bonds in $B$ adjacent to $x$, and give these endpoints an age that is equal to the age of $x$ plus one;
\item we remove $x$ from $S$ and the bonds that contain $x$ from $B$.
\end{enumerate}
\item If $S$ is non-empty, then we repeat the procedure starting in 4) with the updated sets $S$ and $B$.
\end{enumerate}
This procedure terminates when $d_x$ has been defined for all vertices of $A$.



Similarly to the LT case, we define $\nu(A)=\#\{(\mathcal{T},\varphi):\varphi(\mathcal{T})=A, \Ibold^{ \scriptscriptstyle  (a)}(\mathcal{T},\varphi)=1\}$ and now show that
	\begin{align}
	\label{e:Analysis-LA-Poisson-isOne-Tool}
	\nu(A)=\prod_{x\in A}d_x!,
	\end{align}
which implies \eqref{e:Analysis-LA-Poisson-isOne}.

We again prove \eqref{e:Analysis-LA-Poisson-isOne-Tool} by induction on the number $N$ of generations of $A$.
The number of generations corresponds to the age of the oldest particle in $A$. The identity \eqref{e:Analysis-LT-Poisson-isOne-Tool}
clearly holds for $N=0$. Our induction hypothesis is that \eqref{e:Analysis-LT-Poisson-isOne-Tool} holds if there are $N-1$ or fewer generations.

For a LT, the removal of the $d_0$ bonds adjacent to the origin splits the tree into $d_0$ unique, non-intersecting subtrees $T_1,\dots,T_{d_0}$.
Due to possible double connections in a LA, the removal of the bonds adjacent to the origin does not automatically split the animal into $d_0$ uniquely defined sub-animals $A_a$. We will now create a unique split of the animal $A$, that is consistent with the exploration process that we have used to define $(d_x)_x$.

For this, we first remove a certain set of bonds to create a LT $T\subseteq A$. Then we split the $T$ into $d_0$ subtrees as done above. In the last step we add each of the removed bonds to the subtrees to create a unique decomposition $A_1,\dots,A_{d_0}$. This procedure is visualized in Figure \ref{BoundLA-Figure-deconstructing-Animal}. In what follows, we explain how the set of bonds is being chosen. We fix a LA $A$.


