\begin{enumerate}[(1)]
\item We orient all bonds of $A$ away from the origin in the intrinsic distance, see Figure \ref{BoundLA-Figure-deconstructing-Animal}, and denote by $\vec A$ the created LA of oriented bonds. Thus, the oriented bonds $b=(x,y)$ are such that the age of $y$ equals that of $x$ plus one (equal ages cannot happen due to the bipartite structure of the hypercubic lattice $\Zbold^d$);

\item For all $x\in \mathbb{Z}^d$ which have multiple ingoing bonds we remove all ingoing bonds from $\vec A$ with the exception of the ingoing bond $(b_i=(\underline{b}_i,\overline{b}_i=x))_i$ that contains the starting point $\underline{b}_i$ with the lowest lexicographic order;

\item We denote the resulting LA by $\vec T$ and the set of all removed oriented bonds by $\vec S$;

\item We know that $\vec A=\vec T\cup \vec S$ and that in fact $\vec T$ is a LT since step (3) leaves at most one ingoing bond for every $x$ (and precisely one for all vertices except for 0). Further, we see that $\vec T$ contains the same set of vertices as $A$, so that $\vec{T}$ can also be considered a spanning tree of the graph $A$;

\item We delete from $\vec T$ all bonds incident to the origin and denote the created LTs by $\vec T_1,\dots,\vec T_{d_0}$;
\item For $i=1,\dots, d_0$, we define
	\begin{align}
	\vec A_i=\vec T_i\cup\{ b\in \vec S \mid \underline{b}\in \vec T_i\},
	\end{align}
and $A_i$ to be the LA obtained by removing the orientation of the bonds of $\vec A_i$.
\end{enumerate}
We regard $A_{i}$ as rooted at the unique vertex in it that was directly connected to the origin in $A$.
We see that for all $i=1,\dots,d_0$ and $x\in A_i$, the number $d_x$ corresponds to the number of outgoing edges of $x$ in $A_i$.
We note that for all bonds $b\in \vec S\cup \vec A_i$, the end-vertex $\overline{b}$ has no outgoing bonds. This is related to the condition $(2)$ of the definition of $\Ibold^{ \scriptscriptstyle  (a)}(\mathcal{T},\varphi)$.


It suffices to show that $\nu(A)=d_0!\prod_{a=1}^{d_0}\nu(A_{a})$, since each $A_{i}$ has at most $N-1$ generations. We note that each $(\mathcal{T},\varphi)$ with $\varphi(\mathcal{T})=A$ induces a Poisson-NBBRW $(\mathcal{T}_{a},\varphi_{a})$ such that $\varphi_a(\mathcal{T}_{a})=A_{a}$. This correspondence is $d_0!$ to $1$, since $(\mathcal{T},\varphi)$ is determined by the set of $(\mathcal{T}_{a},\varphi_{a})$, up to permutations of the branches of $\mathcal{T}$ at its root. This proves $\nu(A)=d_0!\prod_{a=1}^{d_0}\nu(A_{a})$. This completes the proof of \eqref{e:Analysis-LA-Normalizer-Solved}.


Knowing that \eqref{e:Analysis-LA-Normalizer-Solved} holds, we repeat the steps between \eqref{e:Analysis-LT-Lemma-laststep} and \eqref{e:Analysis-LT-Lemma-nextto-laststep} for LAs, and obtain the claimed bound on $t^{ \scriptscriptstyle  (a)}_n(0)$, which completes the proof of Lemma \ref{lemmaAnalysisLABound}.

\label{Lemma-Mono-SRW}
Let $|x|_{ \scriptscriptstyle  \infty}$ be the supremum norm of $x\in \Zbold^d$. Then, for every $n\geq 1$ and $x^{ \scriptscriptstyle (d)}\in \Zbold^d$ with $|x^{ \scriptscriptstyle (d)}|_{ \scriptscriptstyle  \infty}\leq 2$,
	\begin{equation} 
	I_{n,0}^{ \scriptscriptstyle (d)}(x^{ \scriptscriptstyle (d)})\geq I_{n,0}^{ \scriptscriptstyle (d+1)}(x^{ \scriptscriptstyle (d+1)}),
	 \end{equation}
where $x^{ \scriptscriptstyle (d+1)}_i=x^{ \scriptscriptstyle (d)}_i$ for $i\in\{1,\dots,d\}$, while $x^{ \scriptscriptstyle (d+1)}_{d+1}=0$.

Equation \cite[(B.2)]{HarSla92b}, states, after a rescaling of the $t$ variable, that
	\begin{equation} 
	I_{n,0}^{ \scriptscriptstyle (d)}(x^{ \scriptscriptstyle (d)})=\frac{1}{(n-1)!} \int_0^\infty dt\ t^{n-1} \prod_{\mu=1}^d f_{|x^{ \scriptscriptstyle (d)}_i|}(t/d)dt,
	 \end{equation}
where
	\begin{equation} 
	\label{fN-def}
	f_{N}(z) = \int_{-\pi}^{\pi} \frac{d\theta}{2\pi} {\mathrm e}^{-z[1-\cos(\theta)]} \cos(N\theta).
	 \end{equation}
Let $\ell_1$ be the number of coordinates equal to $\pm 1$ in $x^{ \scriptscriptstyle (d)}$, and $\ell_2$ the number of coordinates equal to $\pm2$ in $x^{ \scriptscriptstyle (d)}$. Then,
	\begin{equation} 
	I_{n,0}^{ \scriptscriptstyle (d)}(x^{ \scriptscriptstyle (d)})=\frac{1}{(n-1)!} \int_0^\infty t^{n-1} f_{0}(t/d)^d \Big(\frac{f_{1}(t/d)}{f_{0}(t/d)}\Big)^{\ell_1} \Big(\frac{f_{2}(t/d)}{f_{0}(t/d)}\Big)^{\ell_2} dt.
	 \end{equation}
Denoting the $L_p(-\pi,\pi)$ norm of $g_s(\theta):=\exp(-s(1-\cos\theta))$ by $\|g_s\|_p$, we obtain by \eqref{fN-def} that
$f_0(s/d)^d=\|g_s\|_{1/d}$, which is monotone decreasing in $d$ for fixed $s$. This already yields the statement for $x^{ \scriptscriptstyle (d)}=0$.

As shown by Hara and Slade \cite[Proof of Lemma C.1]{HarSla92b}, the factor $f_1(s/d)/f_0(s/d)$ is monotone decreasing in $d$, for fixed $s$, because $z\mapsto f_1(z)/f_0(z)$ is monotone increasing in $z>0$.
This can be seen from a direct calculation of its derivative, which gives
	\begin{equation} 
	\frac d {dz} \Big(\frac{f_{1}(z)}{f_{0}(z)}\Big)=\langle\cos^2(\theta)\rangle-\langle\cos(\theta)\rangle^2\geq 0,
	 \end{equation}
where
	\begin{equation} 
	\langle f(\theta)\rangle=\frac {\int_{0}^{2\pi} d\theta\ f(\theta) {\mathrm e}^{z \cos\theta} }{\int_{0}^{2\pi} d\theta {\mathrm e}^{z \cos\theta}}.
	 \end{equation}
This proves the statement for all $x^{ \scriptscriptstyle (d)}$ with $|x^{ \scriptscriptstyle (d)}|_{ \scriptscriptstyle  \infty}=1$, and starts the point where we extend \cite[Lemma C.1]{HarSla92b}.


For even $N$, we use the periodicity of $\cos(\theta)$ and $\cos(N\theta)$, as well as $\cos(N\theta)=\cos(N(\theta+\pi))$ and \eqref{fN-def}, to see that
	\begin{align*}
	f_{2}(z) &={\mathrm e}^{-z}\int_{-\pi/2}^{3\pi/2} \frac{d\theta}{2\pi} {\mathrm e}^{z\cos(\theta)} \cos(N\theta)\\
	&={\mathrm e}^{-z}\int_{-\pi/2}^{\pi/2} \frac{d\theta}{2\pi} \big[\cos(N\theta){\mathrm e}^{z\cos(\theta)}+\cos(N(\theta+\pi)){\mathrm e}^{z\cos(\theta+\pi)})\big]\\
	&={\mathrm e}^{-z}\int_{-\pi/2}^{\pi/2} \frac{d\theta}{2\pi} \cos(N\theta) ({\mathrm e}^{z\cos(\theta)}+{\mathrm e}^{-z\cos(\theta)})
	={\mathrm e}^{-z} \int_{-\pi/2}^{\pi/2} \frac{d\theta}{\pi} \cosh(z\cos(\theta)) \cos(Nz).
	\end{align*}
For odd $N$, the same can be derived where $\cosh$ is replaced by $\sinh$, as $\cos(N\theta)=-\cos(N(\theta+\pi))$ for odd $N$, but we will not rely on this fact.

Using a uniform random variable $U$ on $[-\pi/2,\pi/2]$, we can rewrite the above as
	\begin{align} 
	\frac{d}{d z} \frac{f_{2}(z)}{f_{0}(z)}
	&=\frac{\expec[\sinh(z\cos(U)) \cos(2U)\cos(U)]}{\expec[\cosh(z\cos(U))]}\\
	&\qquad-\frac{\expec[\cosh(z\cos(U)) \cos(2U)]\expec[\sinh(z\cos(U))\cos(U)]}{\expec[\cosh(z\cos(U))]^2}.\nonumber
	 \end{align}
Using the random variable $X$ with density $f_{ \scriptscriptstyle  X}(z)=\cosh(zx)/\int_0^\pi \cosh(zy)dy$, we can simplify
	\begin{equation} 
	\frac{d}{d z} \frac{f_{2}(z)}{f_{0}(z)}=\mathrm{Cov}(\tanh(z\cos(X)) \cos(X),\cos(2X)).
	 \end{equation}
Then, we note that $\cos(2x)=2\cos(x)^2-1$, so
	\begin{align} 
	\frac{d}{d z} \frac{f_{2}(z)}{f_{0}(z)}&=\mathrm{Cov}(\tanh(z\cos(X)) \cos(X),2\cos(X)^2-1)\nonumber\\
	&=2\mathrm{Cov}(\tanh(z\cos(X)) \cos(X),\cos(X)^2).
	 \end{align}
Finally, let $Y=\cos(X)$, which is non-negative as $X\in [-\pi/2,\pi/2]$, to conclude
	\begin{equation} 
	\frac{d}{d z} \frac{f_{2}(z)}{f_{0}(z)}=2\mathrm{Cov}(\tanh(zY) Y,Y^2).
	 \end{equation}
Since both $y\mapsto \tanh(zy) y$ as well as $y\mapsto y^2$ are increasing on $[0,1]$, the above covariance is non-negative. Here we use that $\mathrm{Cov}(f(Y),g(Y))\geq0$ when both $f$ and $g$ are increasing on the support of $Y$, with strict inequality when both are not constant.
\qed

\label{Lemma-SmallSteps}
Fix $n$ and $x$. Let $c_n(x)$ be the number of $n$-step paths from 0 to $x$ of any type and $\mathrm{dim}(x)$ be the dimensionality of $x$, i.e.,
	\begin{align*}
	\mathrm{dim}(x)&:=\#\{\text{\rm{non-zero coordinates of $x$}}\}.
	\end{align*}
Then, $d\mapsto c_n(x)/(2d-1)^n$ is monotonically decreasing in $d$ for
$2d\geq \max\{2\mathrm{dim}(x)+n-|x|_1, 2n-2\}$.

We define the dimension of a path be the maximal dimension of the points it traverses, and let
	\begin{align*}
	c_n^{ \scriptscriptstyle (d)}(x)&:=\#\{\text{number of paths from $0$ to $x$ which have exactly $d$ dimension}\}.
	\end{align*}
This $c_n^{ \scriptscriptstyle (d)}$ has the following properties, which hold for any type of nearest-neighbor paths:
	\begin{enumerate}[(i)]
  	\item $c_n^{ \scriptscriptstyle (d)}(x)\equiv 0$ when $n<|x|_1$, as there are simply not enough steps $n$ to reach $x$
  	\item $c_n^{ \scriptscriptstyle (d)}(x)\equiv 0$ when $d< \mathrm{dim}(x)$, as the point $x$ lives in larger dimension than $d$.
  	\item $c_n^{ \scriptscriptstyle (d)}(x)\equiv 0$ when $n-|x|_1$ is odd, by parity of the lattice.
  	\item $c_n^{ \scriptscriptstyle (d)}(x)\equiv 0$ when $d>\mathrm{dim}(x)+\tfrac {n-|x|_1}2$, as the path can simply not use all the required dimensions $d$ and still reach $x$ in $n$ steps.
	\end{enumerate}
By grouping the paths from $0$ to $x$ according to the number of dimensions $d'$ used, regarding the properties above,  we obtain
	\begin{align*}
	c_n(x)=&\sum_{d'=\mathrm{dim}(x)}^{\mathrm{dim}(x)+\tfrac {n-|x|_1} 2} {d-\mathrm{dim}(x) \choose  d'-\mathrm{dim}(x)}c^{ \scriptscriptstyle (d')}_n(x)
	=\sum_{d'=0}^{\tfrac {n-|x|_1}2} {d-\mathrm{dim}(x) \choose  d'}c^{ \scriptscriptstyle (d'+\mathrm{dim}(x))}_n(x).
	\end{align*}
The binomial coefficient represents the free choices for the additional dimensions $d'$, not imposed by $x$ itself, that the path uses.
We then write
	\begin{equation} 
	\frac {c_n(x)}{(2d-1)^n}=\sum_{d'=0}^{\tfrac {n-|x|_1}2 } f_n(d',d,x)c^{ \scriptscriptstyle (d'+\mathrm{dim}(x))}_n(x),
	 \end{equation}
where
	\begin{equation} 
	f_n(d',d,x):=  \frac { {d-\mathrm{dim}(x) \choose  d'} }{(2d-1)^n}.
	 \end{equation}
Our restriction to $2d\geq 2\mathrm{dim}(x)+n-|x|_1$ ensures that each summand contributes, which allows us to conclude the
required monotonicity of $d\mapsto c_n(x)/(2d-1)^n$ by showing that $d\mapsto f_n(d',d+1)$ is monotonically decreasing for every $d'$ fixed.
 For this, we need to show that
	\begin{equation} 
	\frac {f_n(d',d+1,x)}{f_n(d',d,x)}=\frac {d+1-\mathrm{dim}(x)}{d+1-\mathrm{dim}(x)-d'} \Big(\frac {2d-1}{2d+1}\Big)^n,
	 \end{equation}
is smaller than one. The first fraction is monotone increasing in $\mathrm{dim}(x)$ and $d'$.
We use that $d'\leq \tfrac {n-|x|_1}2$, $\mathrm{dim}(x)\leq |x|_1$ and then $n\geq |x|_1\geq 0$ to obtain
	\begin{align} 
	\label{ratio-bd-1}
	\frac {d+1-\mathrm{dim}(x)}{d+1-\mathrm{dim}(x)-d'} &\leq
	\frac {d+1-|x|_1}{d+1-|x|_1-\tfrac {n-|x|_1}2}=1+\frac {n-|x|_1}{2d+2-|x|_1-n}\\
	&\leq 1+\frac {n}{2d+2-n}=\frac{2d+2}{2d+2-n},
	 \end{align}
where the final inequality follows since $n\leq d+1$.
For the second fraction we note that $(1+y)^n\leq 1+yn+y^2n(n-1)/2$

for all $n\leq y$ and $y>-1$, so that




	\begin{align*}
 	\Big(\frac {2d-1}{2d+1}\Big)^n=\Big(1-\frac {2}{2d-1}\Big)^n\leq 1-\frac {2n}{2d-1}+\frac{2n(n-1)}{(2d-1)^2}
	=\frac {(2d-1)^2-2n(2d-1)+2n(n-1)}{(2d-1)^2}.
	\end{align*}
Combining both bounds, we obtain
	\begin{align} 
	\frac {f_n(d',d+1,x)}{f_n(d',d,x)}&\leq \frac {(2d-1)^2-2n(2d-1)+2n(n-1)}{(2d-1)^2}\frac{2d+2}{2d+2-n}\\
	&=1+\frac {n(2d-1)^2-2n(2d-1)(2d+2)+n(n-1)(2d+2)}{(2d-1)^2(2d+2-n)}\nonumber\\
	&=1+n\frac{(2d-1)^2-2(2d-1)(2d+2)+(n-1)(2d+2)}{(2d-1)^2(2d+2-n)}.\nonumber
	 \end{align}
We finally note that, since $n\leq d$,
	\begin{align} 
	&(2d-1)^2-2(2d-1)(2d+2)+(n-1)(2d+2)\\
	&\qquad\leq (2d-1)^2-2(2d-1)^2+(d-1)(2d+2)
	=2(d^2-1)-(2d-1)^2<0,\nonumber
	 \end{align}
when $d\geq 1$.









\qed
